import subprocess
from kubernetes import client, config
config.load_kube_config()
_v1 = client.CoreV1Api()

def _tail_logs(namespace, name):
    # Fetch the last few log lines for the pod using kubectl
    result = subprocess.run(['kubectl', 'logs', name, '-n', namespace, '--all-containers', '--tail=20'], capture_output=True, text=True, timeout=15)
    return result.stdout

def _summarize(pod):
    statuses = pod.status.container_statuses or []
    waiting = []
    for cs in statuses:
        if cs.state and cs.state.waiting:
            waiting.append(cs.state.waiting.reason)
    return {'name': pod.metadata.name, 'phase': pod.status.phase, 'node': pod.spec.node_name, 'restarts': sum((cs.restart_count for cs in statuses)), 'waiting_reasons': waiting, 'recent_logs': _tail_logs(pod.metadata.namespace, pod.metadata.name)}

def find_unready_pods(namespace: str, label_selector: str=''):
    pods = _v1.list_namespaced_pod(namespace, label_selector=label_selector)
    unready = []
    for pod in pods.items:
        statuses = pod.status.container_statuses or []
        all_ready = bool(statuses) and all((cs.ready for cs in statuses))
        if pod.status.phase == 'Succeeded':
            continue
        if pod.status.phase != 'Running' or not all_ready:
            unready.append(_summarize(pod))
    return {'namespace': namespace, 'count': len(unready), 'pods': unready}
